'use strict';

// MODULES //

var pow = require( '@stdlib/math/base/special/pow' );


// VARIABLES //

var LEARNING_RATE_METHODS = {
	'basic': basic,
	'invscaling': invscaling,
	'pegasos': pegasos
};


// FUNCTIONS //

/**
* Computes learning rate by applying the basic learning rate scheduler.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {NonNegativeInteger} t - current iteration.
* @param {Float64Array} params - strided array containing scheduler specific parameters.
* @returns {number} learning rate
*/
function basic( t, params ) { // eslint-disable-line no-unused-vars
	return 10.0 / ( 10.0*t );
}

/**
* Computes learning rate by applying the inverse scaling learning rate scheduler.
*
* Note:
*
* -   Here `params` => `[ eta0, powerT ]`
*
* @private
* @param {NonNegativeInteger} t - current iteration.
* @param {Float64Array} params - strided array containing scheduler specific parameters.
* @returns {number} learning rate
*/
function invscaling( t, params ) {
	return params[ 0 ] / pow( t, params[ 1 ] );
}

/**
* Computes learning rate by applying the Pegasos learning rate scheduler.
*
* Note:
*
* -   Here `params` => `[ lambda ]`
*
* @private
* @param {NonNegativeInteger} t - current iteration.
* @param {Float64Array} params - strided array containing scheduler specific parameters.
* @returns {number} learning rate
*/
function pegasos( t, params ) {
	return 1.0 / ( params[ 0 ]*t );
}


// EXPORTS //

module.exports = LEARNING_RATE_METHODS;
